#!/usr/bin/env bash
set -euo pipefail
EXPECTED_OLD=3336446403ea39391e05f0b0b4d2f2189817cf48962e05df1950df552f2f8564
EXPECTED_NEW=6ffd7b3ef6c141754d4381c43c33767c3d8f265833f06a7fccb7518bba818bd9
SPEC=specification/closed-loop-reliability-controlling-implementation-specification.txt
actual_old=$(sha256sum "$SPEC" | awk '{print $1}')
test "$actual_old" = "$EXPECTED_OLD"
cat > /tmp/current-spec.patch.gz.b64 <<'PATCH'

PATCH
base64 -d /tmp/current-spec.patch.gz.b64 | gzip -d > /tmp/current-spec.patch
git apply --check /tmp/current-spec.patch
git apply /tmp/current-spec.patch
actual_new=$(sha256sum "$SPEC" | awk '{print $1}')
test "$actual_new" = "$EXPECTED_NEW"
test "$(wc -c < "$SPEC")" -eq 309472
python3 - <<'PY'
from pathlib import Path
b=Path('specification/closed-loop-reliability-controlling-implementation-specification.txt').read_bytes()
assert not b.startswith(b'\xef\xbb\xbf')
assert b'\r' not in b
assert not b.startswith(b'\n')
assert b.endswith(b'\n') and not b.endswith(b'\n\n')
PY
git rm -- verification/.apply-current-spec-source.sh .github/workflows/apply-current-spec-source.yml
git add -- "$SPEC"
git config user.name closed-loop-controller
git config user.email closed-loop-controller@users.noreply.github.com
git commit -m 'Stage 01A: materialize current controlling specification source'
git push origin HEAD:"${GITHUB_HEAD_REF}"
